177	Vec2 PhysicsHelper::computePolygonCenter(const Vec2* verts, int count)
178	{
179	    if (verts == nullptr || count <= 0)
180	        return Vec2::ZERO;
181	
182	    if (count == 1)
183	        return verts[0];
184	
185	    if (count == 2)
186	        return (verts[0] + verts[1]) * 0.5f;
187	
188	    if (polygonArea(verts, count) > kHelperEpsilon)
189	    {
190	        std::vector<cpVect> cpvs(count);
191	        points2cpvs(verts, cpvs.data(), count);
192	        return cpv2point(cpCentroidForPoly(count, cpvs.data()));
193	    }
194	
195	    // Degenerate (zero area) outline, fall back to the average of the vertices.
196	    Vec2 sum(0.0f, 0.0f);
197	    for (int i = 0; i < count; ++i)
198	    {
199	        sum += verts[i];
200	    }
201	
202	    return sum / static_cast<float>(count);
203	}
